-- Схема одной тестовой базы. Загрузчик её не создаёт: миграции — отдельный шаг (LD-R9).
-- Колонки — бриф P1. Ключ catalog.load включает environment, чтобы строка prod
-- добавлялась рядом со staging и не переписывала её (LD-R4).

CREATE SCHEMA catalog;

CREATE TABLE catalog.revision (
    entity_id text NOT NULL,
    catalog_version_from integer NOT NULL,
    content_hash text NOT NULL,
    data jsonb NOT NULL,
    PRIMARY KEY (entity_id, catalog_version_from)
);

CREATE TABLE catalog.load (
    catalog_version integer NOT NULL,
    commit text NOT NULL,
    loaded_at timestamptz NOT NULL,
    environment text NOT NULL,
    PRIMARY KEY (catalog_version, environment),
    CONSTRAINT load_environment CHECK (environment IN ('staging', 'prod'))
);

CREATE TABLE catalog.core_call (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    kind text NOT NULL,
    catalog_version integer NOT NULL,
    payload jsonb NOT NULL,
    CONSTRAINT core_call_kind CHECK (kind IN ('version', 'recheck'))
);

-- Роль брифа. LOGIN нужен только тестовому DSN: у роли нет UPDATE, DELETE и CREATE.
CREATE ROLE loader LOGIN;
REVOKE ALL ON SCHEMA catalog FROM PUBLIC;
GRANT USAGE ON SCHEMA catalog TO loader;
REVOKE ALL ON TABLE catalog.revision, catalog.load, catalog.core_call FROM PUBLIC;
GRANT SELECT, INSERT ON TABLE catalog.revision, catalog.load, catalog.core_call TO loader;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA catalog TO loader;
